import pytest

from bedrock_protocol import v1001, v2168, v2225

Packet = v2225.ClientboundDebugRendererPacket

# TODO: confirm against BDS: gophertunnel's packet.ClientBoundDebugRenderer still writes the pre-cereal body,
# BDS dumps a presence flag ahead of the marker and a one-int32 colour, so gophertunnel has to give.
# generated by gophertunnel b8bd735:
# &packet.ClientBoundDebugRenderer{Type: packet.ClientBoundDebugRendererAddCube, Text: "marker",
# Position: mgl32.Vec3{1, 2, 3}, Duration: 1500}
ADD_CUBE = bytes.fromhex(
    "1261646464656275676d61726b657263756265"
    "01"  # TODO: patched, confirm against BDS
    "066d61726b6572"
    "0000803f0000004000004040"
    "77665544"  # TODO: patched, confirm against BDS
    "dc05000000000000"
)

GOLDENS = [
    pytest.param(
        Packet(
            type=Packet.PayloadType.ADD_DEBUG_MARKER_CUBE,
            debug_marker_data=Packet.DebugMarkerData(
                text="marker",
                position=v2225.Vec3(x=1.0, y=2.0, z=3.0),
                color=0x44556677,
                duration_ms=1500,
            ),
        ),
        ADD_CUBE,
        id="add-cube",
    ),
]

ROUND_TRIPS = [
    pytest.param(Packet(type=Packet.PayloadType.INVALID), id="absent-marker"),
    pytest.param(
        Packet(
            type=Packet.PayloadType.CLEAR_DEBUG_MARKERS,
            debug_marker_data=Packet.DebugMarkerData(
                text="",
                position=v2225.Vec3(x=0.0, y=0.0, z=0.0),
                color=-1,
                duration_ms=255,
            ),
        ),
        id="marker-on-a-clear",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_clientbound_debug_renderer_is_packet_164(version):
    assert version.PACKETS[164] is version.ClientboundDebugRendererPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_debug_renderer_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_debug_renderer_decodes_from_its_golden(packet, golden):
    assert Packet.from_bytes(golden) == packet


@pytest.mark.parametrize("packet", ROUND_TRIPS)
def test_clientbound_debug_renderer_round_trips(packet):
    assert Packet.from_bytes(bytes(packet)) == packet
